def transform(grid):
    out=[row[:] for row in grid]
    bg=max(set(v for row in grid for v in row), key=lambda v:sum(row.count(v) for row in grid))
    mark=min(v for v in range(10) if v!=bg and any(v in row for row in grid))
    accent=2
    for r,row in enumerate(grid):
        cols=[c for c,v in enumerate(row) if v==mark]
        for a,b in zip(cols,cols[1:]):
            if b-a==2 and row[a+1]==bg: out[r][a+1]=accent
    return out
